import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  texture,
  uv,
  vec3,
  vec4,
  mix,
  float,
  uniform,
  positionLocal,
  time,
  sin,
  fract,
  dot,
} from 'three/tsl';
import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-hero-headline';
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 4.2;
  const height = 2.625;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ transparent: true });

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  if (map) {
    map.colorSpace = THREE.SRGBColorSpace;
  }

  const inkColor = vec3(0x16 / 255, 0x16 / 255, 0x1d / 255);
  const surfaceColor = vec3(0x0b / 255, 0x0b / 255, 0x10 / 255);

  const vUv = uv();

  // engineered gradient (hard-edged linear ramp, no soft blur)
  const gradientMix = vUv.y.clamp(0.0, 1.0);
  const gradient = mix(surfaceColor, inkColor, gradientMix);

  const baseTex = map ? texture(map, vUv) : vec4(gradient, 1.0);

  // subtle static grain via pseudo-random noise (hash-based, no time dependency for static composition)
  const grainSeed = dot(vUv, vec3(12.9898, 78.233, 0.0).xy);
  const grain = fract(sin(grainSeed).mul(43758.5453));
  const grainAmount = grain.sub(0.5).mul(0.035);

  const composed = mix(vec3(baseTex.r, baseTex.g, baseTex.b), gradient, 0.15).add(vec3(grainAmount, grainAmount, grainAmount));

  material.colorNode = vec4(composed, 1.0);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'home-hero-headline-plane';
  group.add(mesh);

  // Text content — body role, rendered via MSDF font atlas
  const textNode = ctx.fontAtlas.createText({
    text: 'A machined-metal watch atelier landing with catalog, pricing, jo',
    font: 'JetBrains Mono',
    weight: 400,
    size: 0.13,
    color: 0xe8ecf2,
    maxWidth: width - 0.5,
    align: 'left',
    anchor: 'center',
  });
  textNode.position.set(0, -height / 2 + 0.35, 0.01);
  group.add(textNode);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    if (textNode && typeof textNode.userData?.cleanup === 'function') {
      textNode.userData.cleanup();
    }
  };

  return group;
}
